use smaul_native::rl::AutoRl;
use std::env;
fn val(name:&str,default:&str)->String{let a:Vec<String>=env::args().collect();a.windows(2).find(|x|x[0]==name).map(|x|x[1].clone()).unwrap_or_else(||default.into())}
fn main(){let a:Vec<String>=env::args().collect();let model=val("--model","./SmaulNative");let work=val("--work-dir","./rl");let prompts=a.windows(2).filter(|x|x[0]=="--prompt").map(|x|x[1].clone()).collect::<Vec<_>>();if prompts.is_empty(){eprintln!("use --prompt <text>");std::process::exit(2)}let count:usize=val("--responses","8").parse().unwrap();let max_new:usize=val("--max-new-tokens","256").parse().unwrap();let temp:f32=val("--temperature","0.8").parse().unwrap();let top_k:usize=val("--top-k","50").parse().unwrap();let top_p:f32=val("--top-p","0.95").parse().unwrap();let epochs:usize=val("--preference-epochs","3").parse().unwrap();let pref_lr:f32=val("--preference-lr","1e-3").parse().unwrap();let rl_lr:f32=val("--rl-lr","1e-6").parse().unwrap();let clip:f32=val("--clip","0.2").parse().unwrap();let kl:f32=val("--kl-coef","0.02").parse().unwrap();let verify=!a.iter().any(|x|x=="--no-verify");let mut ar=AutoRl::load(model,work).unwrap_or_else(|e|{eprintln!("{e}");std::process::exit(1)});ar.run(&prompts,count,max_new,temp,top_k,top_p,verify,epochs,pref_lr,rl_lr,clip,kl).unwrap_or_else(|e|{eprintln!("{e}");std::process::exit(1)})}
